def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    sep_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}

    def groups(n, separators):
        result, current = [], []
        for i in range(n):
            if i in separators:
                if current:
                    result.append(current)
                    current = []
            else:
                current.append(i)
        if current:
            result.append(current)
        return result

    row_groups = groups(h, sep_rows)
    col_groups = groups(w, sep_cols)

    counts = Counter(
        grid[r][c]
        for r in range(h) if r not in sep_rows
        for c in range(w) if c not in sep_cols
    )
    base = counts.most_common(1)[0][0]

    output = []
    for rs in row_groups:
        row = []
        for cs in col_groups:
            non_base = sum(grid[r][c] != base for r in rs for c in cs)
            row.append(1 if non_base == 2 else base)
        output.append(row)
    return output
